window.bioOf=function(n){
  if(!n) return null;
  var k=String(n).replace(/[\s　]+/g,'');
  if(BIOS[n]) return BIOS[n];
  for(var x in BIOS){ if(x.replace(/[\s　]+/g,'')===k) return BIOS[x]; }
  return null;
};
